1	//! Tests for Innistrad Tier 3 cards: token-generating spells, creatures with
2	//! dies/ETB/death-watch triggers, anthem enchantments, and token mechanics.
3	
4	mod common;
5	
6	use common::*;
7	use mtg_engine::actions::{Action, Target};
8	use mtg_engine::cards::CardRegistry;
9	use mtg_engine::engine;
10	use mtg_engine::sba::check_state_based_actions_with_registry;
11	use mtg_engine::triggers;
12	use mtg_engine::types::*;
13	
14	fn registry() -> CardRegistry {
15	    CardRegistry::with_all_cards()
16	}
17	
18	// ══════════════════════════════════════════════════════════════════
19	// Token-generating spells
20	// ══════════════════════════════════════════════════════════════════
21	
22	/// Midnight Haunting creates two 1/1 Spirit tokens with flying.
23	#[test]
24	fn midnight_haunting_creates_two_spirits() {
25	    let reg = registry();
26	    let mut state = game_at_step(Step::PrecombatMain, P0);
27	
28	    let card = castable_spell(&mut state, &reg, "Midnight Haunting", P0);
29	
30	    state = cast_and_resolve(&state, &reg, card, vec![]);
31	
32	    // Spell goes to graveyard.
33	    assert_eq!(state.get_object(card).unwrap().zone, Zone::Graveyard);
34	
35	    // Two Spirit tokens on the battlefield.
36	    let tokens: Vec<_> = state.objects_in_zone(Zone::Battlefield, P0)
37	        .into_iter()
38	        .filter(|o| o.is_token && o.name == "Spirit")
39	        .collect();
40	    assert_eq!(tokens.len(), 2, "Should have two Spirit tokens");
41	
42	    for t in &tokens {
43	        assert_eq!(t.power, Some(1));
44	        assert_eq!(t.toughness, Some(1));
45	        assert!(t.keywords.contains(&Keyword::Flying), "Spirit tokens should have flying");
46	    }
47	}
48	
