60	
61	    let tokens: Vec<_> = state.objects_in_zone(Zone::Battlefield, P0)
62	        .into_iter()
63	        .filter(|o| o.is_token && o.name == "Zombie")
64	        .collect();
65	    assert_eq!(tokens.len(), 2, "Should have two Zombie tokens");
66	
67	    for t in &tokens {
68	        assert_eq!(t.power, Some(2));
69	        assert_eq!(t.toughness, Some(2));
70	    }
71	}
