77	/// Doomed Traveler creates a 1/1 Spirit token with flying when it dies.
78	#[test]
79	fn doomed_traveler_creates_spirit_on_death() {
80	    let reg = registry();
81	    let mut state = game_at_step(Step::PrecombatMain, P0);
82	
83	    let dt = named_creature(&mut state, &reg, "Doomed Traveler", P0);
84	
85	    // Kill it with lethal damage.
86	    state.get_object_mut(dt).unwrap().damage_marked = 1;
87	    state.events.clear();
88	    check_state_based_actions_with_registry(&mut state, Some(&reg));
89	
90	    assert_eq!(state.get_object(dt).unwrap().zone, Zone::Graveyard,
91	        "Doomed Traveler should be dead");
92	
93	    // Fire death triggers.
94	    triggers::process_triggers(&mut state, &reg);
95	
96	    // Should have a Spirit token.
97	    let spirits: Vec<_> = state.objects_in_zone(Zone::Battlefield, P0)
98	        .into_iter()
99	        .filter(|o| o.is_token && o.name == "Spirit")
100	        .collect();
101	    assert_eq!(spirits.len(), 1, "Should create one Spirit token");
102	    assert_eq!(spirits[0].power, Some(1));
103	    assert_eq!(spirits[0].toughness, Some(1));
104	    assert!(spirits[0].keywords.contains(&Keyword::Flying));
105	}
