141	/// Village Bell-Ringer has flash and untaps all creatures you control on ETB.
142	#[test]
143	fn village_bell_ringer_untaps_creatures() {
144	    let reg = registry();
145	    let mut state = game_at_step(Step::PrecombatMain, P0);
146	
147	    // Two tapped creatures on P0's side.
148	    let c1 = ready_creature(&mut state, P0, 3, 3);
149	    state.get_object_mut(c1).unwrap().tapped = true;
150	    let c2 = ready_creature(&mut state, P0, 2, 2);
151	    state.get_object_mut(c2).unwrap().tapped = true;
152	
153	    // An opponent's tapped creature (should NOT be untapped).
154	    let opp = ready_creature(&mut state, P1, 1, 1);
155	    state.get_object_mut(opp).unwrap().tapped = true;
156	
157	    // Cast Village Bell-Ringer (flash creature, castable anytime).
158	    let vbr = castable_spell(&mut state, &reg, "Village Bell-Ringer", P0);
159	
160	    state = cast_and_resolve(&state, &reg, vbr, vec![]);
161	
162	    // Process ETB triggers.
163	    triggers::process_triggers(&mut state, &reg);
164	
165	    assert_eq!(state.get_object(vbr).unwrap().zone, Zone::Battlefield);
166	    assert!(!state.get_object(c1).unwrap().tapped,
167	        "P0's creature should be untapped by Village Bell-Ringer");
168	    assert!(!state.get_object(c2).unwrap().tapped,
169	        "P0's second creature should also be untapped");
170	    assert!(state.get_object(opp).unwrap().tapped,
171	        "Opponent's creature should NOT be untapped");
172	}
