174	/// Slayer of the Wicked destroys a Vampire, Werewolf, or Zombie on ETB.
175	#[test]
176	fn slayer_of_the_wicked_destroys_zombie() {
177	    let reg = registry();
178	    let mut state = game_at_step(Step::PrecombatMain, P0);
179	
180	    // P1 has a Walking Corpse (Zombie) on the battlefield.
181	    let wc = named_creature(&mut state, &reg, "Walking Corpse", P1);
182	
183	    // Cast Slayer of the Wicked.
184	    let slayer = castable_spell(&mut state, &reg, "Slayer of the Wicked", P0);
185	
186	    state = cast_and_resolve(&state, &reg, slayer, vec![]);
187	
188	    // Process ETB triggers — Slayer presents an optional choice.
189	    triggers::process_triggers(&mut state, &reg);
190	
191	    // Choose to destroy the Walking Corpse.
192	    if state.awaiting_action.is_some() {
193	        state = engine::submit_action(
194	            &state,
195	            &Action::ResolveChoice {
196	                choice: mtg_engine::actions::ResolvedChoice::ChosenTarget(Some(Target::Object(wc))),
197	            },
198	            &reg,
199	        );
200	        check_state_based_actions_with_registry(&mut state, Some(&reg));
201	    }
202	
203	    assert_eq!(state.get_object(slayer).unwrap().zone, Zone::Battlefield,
204	        "Slayer should be on the battlefield");
205	    assert_eq!(state.get_object(wc).unwrap().zone, Zone::Graveyard,
206	        "Walking Corpse (Zombie) should be destroyed by Slayer of the Wicked");
207	}
